+/** Picks the best supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of raw.split(",")) {
+    const [tagPart, ...params] = part.split(";");
+    const primary = tagPart.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(primary)) continue;
+    let q = 1;
+    let validQ = true;
+    for (const param of params) {
+      const eq = param.indexOf("=");
+      if (eq === -1) continue;
+      if (param.slice(0, eq).trim().toLowerCase() !== "q") continue;
+      const qVal = param.slice(eq + 1).trim();
+      const parsed = Number(qVal);
+      if (!qVal || !Number.isFinite(parsed) || parsed < 0 || parsed > 1) {
+        validQ = false;
+        break;
+      }
+      q = parsed;
+    }
+    if (!validQ || q <= 0) continue;
+    if (q > bestQ) {
+      bestQ = q;
+      bestLang = primary;
+    }
+  }
+  return bestLang ?? fallback;
+}
